// === Tab: mySketch ===
// attractor_6.0

let N = 10000 ; let M = 3 ; let dT = 0.01 ; let B = 40 ; let A = 0.4 ;

let X[] = new Array(N) ; let Y[] = new Array(N) ; 
let CX[] = new Array(M) ; let CY[] = new Array(M) ; let F[] = new Array(M) ;
let dX ; let dY ; let I ; let II ; let L ; let KX ; let KY ; let T ; 



function setup(){

  createCanvas(400, 400) ; noSmooth() ; background(0) ; stroke(255,0,0) ;

  for ( I = 0 ; I < N ; I++ ){
    X[I] = 80*sin(I*2*PI/N) ; Y[I] = 80*cos(I*2*PI/N) ;
  }

  for ( II = 0 ; II < M ; II++ ){
    F[II] = random(3,6) ;
    CX[II] = 100*sin(II*2*PI/M) ; CY[II] = 100*cos(II*2*PI/M) ;
  }

} // setup()



function draw(){

  background(0) ;

  for ( I = 0 ; I < N ; I++ ){
    dX = 0 ; dY = 0 ; 
    for ( II = 0 ; II < M ; II++ ){
      KX = X[I]-CX[II] ; KY = Y[I]-CY[II] ;
      L = sqrt((KX*KX)+(KY*KY)) ;
      dX = dX + ((+KY-(KX*A*sin(F[II]*T)))/L/L) ;
      dY = dY + ((-KX-(KY*A*sin(F[II]*T)))/L/L) ;
    }
    dX = dX*B ; dY = dY*B ; 
    point(X[I]+200,Y[I]+200) ;
    X[I] = X[I] + dX ; Y[I] = Y[I] + dY ;
  }

  for ( II = 0 ; II < M ; II++ ){
    CX[II] = 100*sin(II*2*PI/M-T) ; CY[II] = 100*cos(II*2*PI/M-T) ;
  }

  T = T + dT ;

} // draw()



function mousePressed(){ setup() ; }

